"""Prototype: inventory counts -> supplier order draft (par-level logic)."""
import csv, sys

def order_draft(counts, pars):
    """counts/pars: dict item -> quantity. Returns dict of items to order."""
    return {item: pars[item] - counts.get(item, 0)
            for item in pars if counts.get(item, 0) < pars[item]}

if __name__ == "__main__":
    counts = {"chicken thighs": 4, "rice (lb)": 30, "limes": 10}
    pars = {"chicken thighs": 12, "rice (lb)": 25, "limes": 10}
    for item, qty in order_draft(counts, pars).items():
        print(f"ORDER {qty} x {item}")
EOF
