"""Prototype: inventory counts -> supplier order draft (par-level logic).

Rounds up to supplier case size and logs items with no count or par
so misses are visible during a pilot.
"""
import math

def order_draft(counts, pars, case_sizes=None, log=None):
    """counts/pars: dict item -> quantity. case_sizes: dict item -> units per case.
    Returns dict item -> units to order (rounded up to whole cases)."""
    case_sizes = case_sizes or {}
    order = {}
    for item, par in pars.items():
        if item not in counts:
            if log is not None:
                log.append(f"MISSING COUNT: {item}")
            continue
        short = par - counts[item]
        if short <= 0:
            continue
        size = case_sizes.get(item, 1)
        order[item] = math.ceil(short / size) * size
    for item in counts:
        if item not in pars and log is not None:
            log.append(f"NO PAR SET: {item}")
    return order

if __name__ == "__main__":
    counts = {"chicken thighs": 4, "rice (lb)": 30, "limes": 10}
    pars = {"chicken thighs": 12, "rice (lb)": 25, "limes": 10}
    cases = {"chicken thighs": 6}
    misses = []
    for item, qty in order_draft(counts, pars, cases, misses).items():
        print(f"ORDER {qty} x {item}")
    for m in misses:
        print(m)
EOF
